export function checkoutTotal(lines, discountCents = 0) {
  const subtotal = lines.reduce((sum, line) => {
    if (!Number.isInteger(line.quantity) || line.quantity < 1) throw new Error("Invalid quantity");
    if (!Number.isInteger(line.unitPriceCents) || line.unitPriceCents < 0) throw new Error("Invalid unit price");
    return sum + line.quantity * line.unitPriceCents;
  }, 0);
  if (!Number.isInteger(discountCents) || discountCents < 0 || discountCents > subtotal) throw new Error("Invalid discount");
  return subtotal - discountCents;
}

